#include "GeologyRuntime.hpp"
namespace elysium::world {bool GeologyRuntime::addLayer(GeologicalLayer l,std::string&w){if(!l.id||l.maxDepth<=l.minDepth){w="invalid layer";return false;}auto clamp=[](double v){return std::clamp(std::isfinite(v)?v:0.0,0.0,1.0);};l.permeability=clamp(l.permeability);l.porosity=clamp(l.porosity);l.aquiferChance=clamp(l.aquiferChance);l.volatileChance=clamp(l.volatileChance);l.structuralTendency=std::max(0.0,std::isfinite(l.structuralTendency)?l.structuralTendency:0.0);layers_.push_back(std::move(l));std::sort(layers_.begin(),layers_.end(),[](auto&a,auto&b){return a.minDepth<b.minDepth;});return true;}double GeologyRuntime::noise(std::uint64_t a,std::uint64_t d)const{std::uint64_t x=seed_^a^(d*0x9e3779b97f4a7c15ULL);x^=x>>30;x*=0xbf58476d1ce4e5b9ULL;x^=x>>27;x*=0x94d049bb133111ebULL;x^=x>>31;return double(x>>11)/double(1ULL<<53);}std::optional<GeologySample> GeologyRuntime::sample(std::uint64_t c,double depth)const{for(auto&l:layers_)if(depth>=l.minDepth&&depth<l.maxDepth){auto a=noise(c,l.id);auto v=noise(c,l.id^0xA5A5);auto cv=noise(c,l.id^0xC0FFEE);return GeologySample{l.id,a<l.aquiferChance?a*l.permeability:0.0,v<l.volatileChance?v*l.porosity:0.0,l.structuralTendency,cv};}return std::nullopt;}}
